import { DefaultChannel } from './DefaultChannel.js';
import { PrivateChannelNullEventListener, PrivateChannelAddContextEventListener, PrivateChannelDisconnectEventListener, PrivateChannelUnsubscribeEventListener, } from '../listeners/PrivateChannelEventListener.js';
import { DefaultContextListener } from '../listeners/DefaultContextListener.js';
export class DefaultPrivateChannel extends DefaultChannel {
    constructor(messaging, messageExchangeTimeout, id) {
        super(messaging, messageExchangeTimeout, id, 'private');
        //bind all functions to allow destructuring
        this.addContextListener = this.addContextListener.bind(this);
        this.addEventListener = this.addEventListener.bind(this);
        this.disconnect = this.disconnect.bind(this);
    }
    async addEventListener(type, handler) {
        let a;
        switch (type) {
            case 'addContextListener':
                a = new PrivateChannelAddContextEventListener(this.messaging, this.messageExchangeTimeout, this.id, handler);
                break;
            case 'unsubscribe':
                a = new PrivateChannelUnsubscribeEventListener(this.messaging, this.messageExchangeTimeout, this.id, handler);
                break;
            case 'disconnect':
                a = new PrivateChannelDisconnectEventListener(this.messaging, this.messageExchangeTimeout, this.id, handler);
                break;
            case null:
                a = new PrivateChannelNullEventListener(this.messaging, this.messageExchangeTimeout, this.id, handler);
                break;
            default:
                throw new Error('Unsupported event type: ' + type);
        }
        await a.register();
        return a;
    }
    //implementations of the deprecated listener functions
    onAddContextListener(handler) {
        //Adapt handler type for differences between addEventListener and onAddContextListener handler types
        const adaptorHandler = (event) => {
            handler(event.details.contextType ?? undefined);
        };
        const l = new PrivateChannelAddContextEventListener(this.messaging, this.messageExchangeTimeout, this.id, adaptorHandler);
        l.register();
        return l;
    }
    onUnsubscribe(handler) {
        //Adapt handler type for differences between addEventListener and onUnsubscribeListener handler types
        const adaptorHandler = (event) => {
            handler(event.details.contextType ?? undefined);
        };
        const l = new PrivateChannelUnsubscribeEventListener(this.messaging, this.messageExchangeTimeout, this.id, adaptorHandler);
        l.register();
        return l;
    }
    onDisconnect(handler) {
        //Adapt handler type for differences between addEventListener and onDisconnectListener handler types
        const adaptorHandler = () => {
            handler();
        };
        const l = new PrivateChannelDisconnectEventListener(this.messaging, this.messageExchangeTimeout, this.id, adaptorHandler);
        l.register();
        return l;
    }
    async disconnect() {
        const msg = {
            meta: this.messaging.createMeta(),
            payload: {
                channelId: this.id,
            },
            type: 'privateChannelDisconnectRequest',
        };
        await this.messaging.exchange(msg, 'privateChannelDisconnectResponse', this.messageExchangeTimeout);
    }
    async addContextListenerInner(contextType, theHandler) {
        const listener = new DefaultContextListener(this.messaging, this.messageExchangeTimeout, this.id, contextType, theHandler);
        await listener.register();
        return listener;
    }
}
