export class DefaultIntentResolution {
    messaging;
    source;
    intent;
    result;
    constructor(messaging, result, source, intent) {
        this.messaging = messaging;
        this.result = result;
        this.source = source;
        this.intent = intent;
        //bind all functions to allow destructuring
        this.getResult = this.getResult.bind(this);
    }
    getResult() {
        return this.result;
    }
}
